def maximumXorProduct(a: int, b: int, n: int) -> int:
    MOD = 10**9 + 7
    # We only care about bits from 0 to n-1
    for i in range(n-1, -1, -1):
        bit = 1 << i
        if (a & bit) == (b & bit):
            # If both have same bit, we can flip both to 1 by setting x's bit to opposite
            a |= bit
            b |= bit
        else:
            # If bits differ, we want to give the 1 to the smaller number
            if a > b:
                a ^= bit
            else:
                b ^= bit
    return (a % MOD) * (b % MOD) % MOD
